/* IndexedDB holds complete exports; lightweight summaries drive comparisons. */
let savedRunSummaries=[],selectedRunIds=new Set(),currentRunId=null,currentFitStats=newFitStats(),runDatabasePromise=null;
const cacheEl=id=>document.getElementById(id),cacheColors=['#9ddbc3','#e5ae7a','#9ab9f0','#d5a2df','#e5d58c','#91d5df','#ef9d9d','#b9cb8c'];
function cacheStatus(text){cacheEl('cacheStatus').textContent=text}
function markNewRun(){currentRunId=null;currentFitStats=newFitStats()}
function cacheCandidate(m){accumulateFit(currentFitStats,m)}
function openRunDatabase(){if(runDatabasePromise)return runDatabasePromise;runDatabasePromise=new Promise((resolve,reject)=>{if(typeof indexedDB==='undefined'){reject(Error('Browser storage is unavailable. Current-run plotting and export still work.'));return}const req=indexedDB.open('arcfield-experiments',1);req.onupgradeneeded=()=>{const db=req.result;db.createObjectStore('outputs',{keyPath:'id'});db.createObjectStore('summaries',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('Storage access failed'));req.onblocked=()=>cacheStatus('Storage upgrade is waiting for another Arcfield tab to close.')});return runDatabasePromise}
async function readSavedSummary(){const db=await openRunDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction('summaries','readonly'),r=tx.objectStore('summaries').getAll();r.onsuccess=()=>resolve(r.result.sort((a,b)=>a.savedAt.localeCompare(b.savedAt)));r.onerror=()=>reject(r.error)})}
function runLabel(r){return r.name||r.config.name||r.config.seed}
function renderRunList(){const list=cacheEl('cachedRuns');list.replaceChildren();cacheEl('clearSavedRuns').disabled=!savedRunSummaries.length;savedRunSummaries.forEach((r,i)=>{let row=document.createElement('div');row.className='savedRunRow';let label=document.createElement('label');label.style.color=cacheColors[i%cacheColors.length];let check=document.createElement('input');check.type='checkbox';check.checked=selectedRunIds.has(r.id);check.onchange=()=>{if(check.checked)selectedRunIds.add(r.id);else selectedRunIds.delete(r.id);drawLandscape()};let text=document.createElement('span');text.textContent=`${i+1}. ${runLabel(r)} · seed ${r.config.seed} · ${r.config.cols}×${r.config.rows} · ${r.score} collisions · ${new Date(r.savedAt).toLocaleString()}`;label.append(check,text);let actions=document.createElement('div');actions.className='savedRunActions';let load=document.createElement('button');load.textContent='Load result';load.onclick=()=>loadCachedExperiment(r.id);let rename=document.createElement('button');rename.textContent='Rename';rename.onclick=()=>{const name=window.prompt('Name this run (up to 80 characters):',runLabel(r));if(name!==null)renameCachedExperiment(r.id,name)};let remove=document.createElement('button');remove.textContent='Delete';remove.className='deleteRun';remove.onclick=()=>{if(window.confirm('Delete saved run “'+runLabel(r)+'”? Its cached metrics, winner and export data will be removed. Downloaded files are unaffected.'))deleteCachedExperiment(r.id)};actions.append(load,rename,remove);row.append(label,actions);list.append(row)});if(!savedRunSummaries.length){let p=document.createElement('p');p.textContent='Completed experiments will appear here automatically.';list.append(p)}}
async function cacheCompletedExperiment(){if(!exportRun?.winner)return;const id=currentRunId||((typeof crypto!=='undefined'&&crypto.randomUUID)?crypto.randomUUID():Date.now()+'-'+Math.random().toString(16).slice(2));currentRunId=id;const summary={id,name:exportRun.config.name||exportRun.config.seed,savedAt:new Date().toISOString(),config:structuredClone(exportRun.config),score:exportRun.winner.collisions,topology:structuredClone(exportRun.winner.topology),stats:structuredClone(currentFitStats),points:structuredClone(landscapePoints),latest:structuredClone(landLatest),best:structuredClone(landBest),seen:landSeen,generation:landGen};const record={id,summary,output:structuredClone(exportRun),evolution:structuredClone(evolutionHistory)};cacheStatus('Saving completed experiment in this browser…');try{const db=await openRunDatabase();await new Promise((resolve,reject)=>{const tx=db.transaction(['outputs','summaries'],'readwrite');tx.objectStore('outputs').put(record);tx.objectStore('summaries').put(summary);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Save aborted'))});savedRunSummaries=savedRunSummaries.filter(r=>r.id!==id);savedRunSummaries.push(summary);selectedRunIds.add(id);renderRunList();cacheStatus(savedRunSummaries.length+' completed runs saved in this browser. Select runs to compare.');drawLandscape()}catch(e){cacheStatus('Could not cache this run: '+e.message+' Export it to keep a copy.')}}
async function loadCachedExperiment(id){if(typeof worker!=='undefined'&&worker){cacheStatus('Finish or cancel the current search before loading a saved result.');return}try{let db=await openRunDatabase(),record=await new Promise((resolve,reject)=>{let r=db.transaction('outputs','readonly').objectStore('outputs').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(!record)throw Error('Saved output is missing');restoreCachedExperiment(record);cacheStatus('Loaded '+(record.output.config.name||record.output.config.seed)+'. Its export data and winner replay are available.')}catch(e){cacheStatus('Could not load saved result: '+e.message)}}
function landscapeRunGroups(latest){let comparing=cacheEl('compareRuns').checked,groups=[];if(!landConfig)return groups;const addCurrent=()=>{let points=(latest?landLatest:landscapePoints).slice();groups.push({id:currentRunId||'current',name:'Current · '+(landConfig.name||landConfig.seed),color:'#9ddbc3',points,best:landBest,stats:currentFitStats,seen:landSeen,config:landConfig})};if(!comparing){addCurrent();return groups}savedRunSummaries.forEach((r,i)=>{if(selectedRunIds.has(r.id)){if(r.id===currentRunId){addCurrent();groups[groups.length-1].color=cacheColors[i%cacheColors.length];groups[groups.length-1].name=runLabel(r)}else groups.push({id:r.id,name:runLabel(r),color:cacheColors[i%cacheColors.length],points:(latest?r.latest:r.points).slice(),best:r.best,stats:r.stats,seen:r.seen,config:r.config})}});if(landSeen>0&&!savedRunSummaries.some(r=>r.id===currentRunId))addCurrent();return groups}
cacheEl('compareRuns').onchange=()=>{landSelected=null;drawLandscape()};cacheEl('landDisplay').onchange=()=>{landSelected=null;drawLandscape()};
async function initializeRunHistory(){try{savedRunSummaries=await readSavedSummary();savedRunSummaries.forEach(r=>selectedRunIds.add(r.id));renderRunList();cacheStatus(savedRunSummaries.length+' completed runs restored from this browser.');if(!exportRun&&savedRunSummaries.length){cacheEl('compareRuns').checked=true;await loadCachedExperiment(savedRunSummaries.at(-1).id)}}catch(e){cacheStatus(e.message)}}

async function renameCachedExperiment(id,input){const name=String(input).trim();if(!name||name.length>80){cacheStatus('Use a run name containing 1–80 characters.');return false}try{const db=await openRunDatabase();let updated;await new Promise((resolve,reject)=>{const tx=db.transaction(['outputs','summaries'],'readwrite');const req=tx.objectStore('outputs').get(id);req.onsuccess=()=>{let r=req.result;if(!r){tx.abort();return}r.summary.name=name;r.summary.config.name=name;r.output.config.name=name;if(r.output.winner?.config)r.output.winner.config.name=name;tx.objectStore('outputs').put(r);tx.objectStore('summaries').put(r.summary);updated=r.summary};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Saved run was not found'))});savedRunSummaries=savedRunSummaries.map(r=>r.id===id?updated:r);if(currentRunId===id){landConfig.name=name;exportRun.config.name=name;if(exportRun.winner?.config)exportRun.winner.config.name=name;if(winner?.config)winner.config.name=name;cacheEl('runName').value=name;cacheEl('resultNote').textContent=name+' · seed '+landConfig.seed+' · '+landConfig.generations+' generations.'}renderRunList();drawLandscape();cacheStatus('Renamed saved run to “'+name+'”.');return true}catch(e){cacheStatus('Could not rename run: '+e.message);return false}}
async function removeSavedRecords(id){const db=await openRunDatabase();await new Promise((resolve,reject)=>{const tx=db.transaction(['outputs','summaries'],'readwrite');for(let store of ['outputs','summaries']){if(id)tx.objectStore(store).delete(id);else tx.objectStore(store).clear()}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Removal aborted'))})}
async function deleteCachedExperiment(id){try{await removeSavedRecords(id);savedRunSummaries=savedRunSummaries.filter(r=>r.id!==id);selectedRunIds.delete(id);if(currentRunId===id)currentRunId=null;renderRunList();drawLandscape();cacheStatus('Saved run deleted. Any result already on screen remains available until you refresh or start another run.');return true}catch(e){cacheStatus('Could not delete run: '+e.message);return false}}
async function clearCachedExperiments(){try{await removeSavedRecords(null);savedRunSummaries=[];selectedRunIds.clear();currentRunId=null;renderRunList();drawLandscape();cacheStatus('Saved run history cleared. The offline app and current on-screen experiment are unchanged.');return true}catch(e){cacheStatus('Could not clear saved runs: '+e.message);return false}}
cacheEl('clearSavedRuns').onclick=()=>{if(window.confirm('Clear ALL '+savedRunSummaries.length+' saved runs from this browser? Cached metrics, winners and export data will be deleted. The offline app and downloaded files are kept.'))clearCachedExperiments()};
